#!/usr/bin/env python3
"""Generate packages/omf-formats/src/cp437.ts from Python's cp437 codec."""

import json
import pathlib

OUT = pathlib.Path(__file__).resolve().parent.parent / "packages/omf-formats/src/cp437.ts"

chars = bytes(range(256)).decode("cp437")
OUT.write_text(
    "// Generated by tools/export_cp437.py from Python's cp437 codec. Do not edit.\n"
    f"export const CP437_TO_UNICODE: string = {json.dumps(chars)};\n"
)
print(f"wrote {OUT}")
